<template>
  <SuperAdminLayout>
    <section class="visitor-page">
      <div class="visitor-heading"><h1>4. WEBSITE VISITORS</h1><div class="visitor-kpis"><article class="visitor-kpi"><span class="kpi-icon people"></span><div><small>Total visitors</small><strong>{{ summary.total_visitors || 0 }}</strong></div></article><article class="visitor-kpi"><span class="kpi-icon signup"></span><div><small>Signed up</small><strong>{{ summary.signed_up || 0 }} <em>({{ summary.signup_rate || 0 }}%)</em></strong></div></article><article class="visitor-kpi"><span class="kpi-icon clock"></span><div><small>Avg. spent time</small><strong>{{ summary.average_spent_time || '00:00:00' }}</strong></div></article></div></div>
      <form class="visitor-filters" @submit.prevent="search"><label>From Date<input v-model="filters.from_date" type="date"></label><label>To Date<input v-model="filters.to_date" type="date"></label><label>Sign Up<select v-model="filters.sign_up"><option value="all">All</option><option value="yes">Yes</option><option value="no">No</option></select></label><label>Location<select v-model="filters.location"><option value="all">All</option><option v-for="location in locations" :key="location" :value="location">{{ location }}</option></select></label><div class="filter-actions"><button class="search-button" :disabled="loading">{{ loading ? 'Searching...' : 'Search' }}</button><button class="clear-button" type="button" @click="clear">Clear</button></div></form>
      <div class="visitor-table-wrap"><table class="visitor-table"><thead><tr><th>No.</th><th>Visitor IP</th><th>How Many<br>Times</th><th>Spent Time</th><th>Location</th><th>Sign Up</th><th>First Visit</th><th>Last Visit</th><th>Device</th><th>Browser</th><th>Pages<br>Viewed</th><th>Referral Source</th><th>Sign-Up Date</th><th>View Details</th></tr></thead><tbody><tr v-for="(row, index) in rows" :key="row.visitor_key"><td>{{ ((meta.current_page || 1) - 1) * (meta.per_page || perPage) + index + 1 }}</td><td>{{ row.ip_address || '—' }}</td><td>{{ row.visit_count }}</td><td>{{ row.spent_time || '—' }}</td><td>{{ row.location || 'Unknown' }}</td><td :class="row.signed_up ? 'signed-up' : ''">{{ row.signed_up ? 'Yes' : 'No' }}</td><td>{{ dateTime(row.first_visit) }}</td><td>{{ dateTime(row.last_visit) }}</td><td>{{ row.device || 'Unknown' }}</td><td>{{ row.browser || 'Unknown' }}</td><td>{{ row.pages_viewed }}</td><td>{{ row.referral_source || 'Direct' }}</td><td>{{ row.sign_up_date ? dateOnly(row.sign_up_date) : '—' }}</td><td><button class="details-button" type="button" @click="selected = row">View Details</button></td></tr><tr v-if="!loading && !rows.length"><td colspan="14" class="empty-row">No website visitors found for this period.</td></tr><tr v-if="loading"><td colspan="14" class="empty-row">Loading visitor data...</td></tr></tbody></table></div>
      <footer class="visitor-footer"><strong>Total Visitors: <span>{{ meta.total || 0 }}</span></strong><div class="pagination"><label>Show <select v-model.number="perPage" @change="changePerPage"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select> per page</label><button type="button" :disabled="!meta.prev_page_url" @click="load(1)">|&lt;</button><button type="button" :disabled="!meta.prev_page_url" @click="load((meta.current_page || 1) - 1)">&lt;</button><b>{{ meta.current_page || 1 }}</b><button type="button" :disabled="!meta.next_page_url" @click="load((meta.current_page || 1) + 1)">&gt;</button><button type="button" :disabled="!meta.next_page_url" @click="load(meta.last_page)">&gt;|</button><span>Page {{ meta.current_page || 1 }} of {{ meta.last_page || 1 }}</span></div></footer>
    </section>
    <div v-if="selected" class="details-backdrop" @click.self="selected = null"><section class="details-modal" role="dialog" aria-modal="true" aria-label="Visitor details"><button class="modal-close" type="button" @click="selected = null">×</button><h2>Visitor Details</h2><dl><div><dt>Visitor IP</dt><dd>{{ selected.ip_address || '—' }}</dd></div><div><dt>Visits / pages viewed</dt><dd>{{ selected.visit_count }} / {{ selected.pages_viewed }}</dd></div><div><dt>First / last visit</dt><dd>{{ dateTime(selected.first_visit) }} / {{ dateTime(selected.last_visit) }}</dd></div><div><dt>Device / browser</dt><dd>{{ selected.device }} / {{ selected.browser }}</dd></div><div><dt>Referral source</dt><dd>{{ selected.referral_source || 'Direct' }}</dd></div><div><dt>Visited pages</dt><dd>{{ (selected.pages || []).join(', ') || '—' }}</dd></div></dl></section></div>
  </SuperAdminLayout>
</template>
<script setup>
import { onMounted, ref } from 'vue'
import SuperAdminLayout from '../components/SuperAdminLayout.vue'
import client from '../api/client'
const isoDate = value => new Date(value).toISOString().slice(0, 10)
const today = new Date()
const defaultFilters = () => ({ from_date: isoDate(new Date(today.getFullYear(), today.getMonth(), 1)), to_date: isoDate(today), sign_up: 'all', location: 'all' })
const filters = ref(defaultFilters()), rows = ref([]), summary = ref({}), meta = ref({}), locations = ref([]), loading = ref(false), selected = ref(null), perPage = ref(10)
const dateTime = value => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—'
const dateOnly = value => value ? new Intl.DateTimeFormat('en-US', { month: 'short', day: '2-digit', year: 'numeric' }).format(new Date(value)) : '—'
async function load(page = 1) { loading.value = true; try { const { data } = await client.get('/super-admin/website-visitors', { params: { ...filters.value, per_page: perPage.value, page } }); const result = data.data || {}; rows.value = result.rows?.data || []; meta.value = result.rows || {}; summary.value = result.summary || {}; locations.value = result.locations || [] } finally { loading.value = false } }
const search = () => load(1)
function clear() { filters.value = defaultFilters(); load(1) }
const changePerPage = () => load(1)
onMounted(() => load())
</script>
